const input = $input.first().json;
const body = input.body;
const session = input.session;
const documentHash = input.documentHash;

// Ad-hoc context (scrapes)
const adhocParts = [];

const docs = body.attachedContext || [];

if (docs.length > 0) {

    // If there's only one document, it's obviously the primary one.
    if (docs.length === 1) {

        const doc = docs[0];

        adhocParts.push({
            text:
`PRIMARY DOCUMENT

Filename: ${doc.name}

The user's questions should be answered using this document.

${doc.content}`
        });

    } else {

        // Multiple documents attached.
        // Present the first as the current document and clearly separate the rest.
        const [primary, ...others] = docs;

        adhocParts.push({
            text:
`PRIMARY DOCUMENT

Filename: ${primary.name}

The user's current questions most likely refer to this document unless they explicitly ask to compare documents.

${primary.content}`
        });

        if (others.length) {

            const otherText = others
                .map(doc =>
`### ${doc.name}

${doc.content}`)
                .join("\n\n--------------------------------------------------\n\n");

            adhocParts.push({
                text:
`ADDITIONAL REFERENCE DOCUMENTS

These documents may provide supporting context if needed.

${otherText}`
            });

        }

    }

}

// Cacheable context (KB docs + images)
const cacheableParts = [];
if (body.cachableContext && body.cachableContext.length > 0) {
  const ctxText = body.cachableContext
    .map(c => `### ${c.name}\n${c.content}`)
    .join('\n\n');
  cacheableParts.push({ text: 'Reference material — treat this as the source of truth:\n\n' + ctxText });
}
for (const img of (body.attachedImages || [])) {
  if (!img.data) continue;
  cacheableParts.push({ text: `Attached image: ${img.name}` });
  cacheableParts.push({ inline_data: { mime_type: img.mime || 'image/jpeg', data: img.data } });
}

// Scanned PDFs — handed to Gemini via Files API; n8n owns upload/reuse
// (see "Upload Scanned PDFs"). Cheap to resend every turn: it's just a
// file_uri reference, not the document bytes.
for (const part of (input.geminiFileParts || [])) {
  cacheableParts.push(part);
}

const contents = [];

/*
 * 1. Reference material FIRST
 * This is the authoritative source.
 */
if (adhocParts.length || cacheableParts.length) {

    contents.push({
        role: "user",
        parts: [
            {
                text:
`REFERENCE MATERIAL

The following material is the authoritative source for this conversation.

If any previous assistant response contradicts this material,
the previous response is WRONG.

Always answer using the reference material below.`
            },
            ...adhocParts,
            ...cacheableParts
        ]
    });

}

/*
 * 2. Previous conversation
 */
const MAX_HISTORY = 30;

const previousConversation =
    (session?.conversation || [])
        .slice(-MAX_HISTORY);

for (const m of previousConversation) {

    contents.push({
        role: m.role,
        parts: [
            {
                text: m.text
            }
        ]
    });

}

/*
 * 3. Latest user messages
 */
const latestMessage = body.messages?.at(-1);

if (latestMessage) {

    contents.push({
        role: latestMessage.role,
        parts: [
            {
                text: latestMessage.text
            }
        ]
    });

}

const geminiBody = {
  contents,
  system_instruction: {
    parts: [
      {
        text:
`${body.systemPrompt}

Grounding rules:

• The attached documents are the authoritative source.

• If previous assistant responses contradict the attached documents, correct yourself immediately.

• Never repeat an incorrect previous answer merely for consistency.

• Prefer the attached documents over conversation history.

• If multiple documents exist, answer primarily from the PRIMARY DOCUMENT unless the user explicitly asks to compare them.

• If information is absent from the documents, clearly say so instead of guessing.
`
      }
    ]
  },
  generationConfig: {
    temperature: 0.7,
    maxOutputTokens: 49152
  }
};

return [{
  json: {
    geminiBody,
    sessionId: body.chatId,
    documentHash
  }
}];

const response = $('Gemini — Tutor').first().json;
let text = '';

try {
  const candidates = (response.body && response.body.candidates) || response.candidates || [];
  if (candidates.length > 0) {
    const candidate = candidates[0];
    const reason = candidate.finishReason || '';
    if (reason === 'RECITATION') return { json: { result: '[Transcription blocked] The AI detected this may be published/copyrighted content and cannot reproduce it. Try uploading handwritten notes instead.' } };
    if (reason === 'SAFETY') return { json: { result: '[Blocked] The AI safety filters prevented processing this content.' } };
    if (candidate.content && candidate.content.parts) {
      text = candidate.content.parts.filter(p => p.text).map(p => p.text).join('\n');
    }
  }
  if (!text) throw new Error('No text extracted from Gemini response');
} catch (err) {
  throw new Error(`Tutor Gemini extraction failed: ${err.message}. Raw keys: ${JSON.stringify(Object.keys(response))}`);
}

const prep = $('Prep — Tutor').first().json;

return { json: {
  result: text.trim(),
  cacheName: prep.cacheName || null,
  cacheExpiresAt: prep.cacheExpiresAt || null
} };

const input = $input.first().json;

const status = input.statusCode || (input.body && input.body.error ? 500 : null);
if (input.error || (status && status >= 400)) {
  let message = 'We couldn\'t read this website. It might be protected by a paywall or login screen.';
  if (status === 403) message = 'We couldn\'t read this website — it blocked our request (403 Forbidden).';
  else if (status === 404) message = 'Page not found (404). Double-check the URL.';
  else if (status === 401) message = 'This page requires a login. Please copy the text manually.';
  else if (status === 429) message = 'The site is rate-limiting requests. Try again in a minute.';
  return [{ json: { error: true, message } }];
}

let html = '';
if (input.body && typeof input.body === 'string') html = input.body;
else if (typeof input.data === 'string') html = input.data;

if (!html || html.trim().length < 50) {
  return [{ json: { error: true, message: 'We couldn\'t read this website. It may have returned no content.' } }];
}

// ── YouTube-specific: grab uploadDate before stripping <script> tags ──
let ytUploadDate = '';
const m = html.match(/"uploadDate"\s*:\s*"([^"]+)"/);
if (m) ytUploadDate = m[1];
const m2 = html.match(/"datePublished"\s*:\s*"([^"]+)"/);
if (!ytUploadDate && m2) ytUploadDate = m2[1];

html = html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
html = html.replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '');
html = html.replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, '');
html = html.replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, '');
html = html.replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, '');
html = html.replace(/<aside\b[^<]*(?:(?!<\/aside>)<[^<]*)*<\/aside>/gi, '');
html = html.replace(/<!--[\s\S]*?-->/g, '');

html = html.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n# $1\n');
html = html.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n## $1\n');
html = html.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n### $1\n');
html = html.replace(/<h4[^>]*>([\s\S]*?)<\/h4>/gi, '\n#### $1\n');
html = html.replace(/<h5[^>]*>([\s\S]*?)<\/h5>/gi, '\n##### $1\n');
html = html.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '\n- $1');
html = html.replace(/<\/[uo]l>/gi, '\n');
html = html.replace(/<br\s*\/?>/gi, '\n');
html = html.replace(/<\/p>/gi, '\n\n');
html = html.replace(/<\/div>/gi, '\n');
html = html.replace(/<\/tr>/gi, '\n');
html = html.replace(/<td[^>]*>/gi, ' | ');
html = html.replace(/<th[^>]*>/gi, ' | ');
html = html.replace(/<\/table>/gi, '\n');
html = html.replace(/<hr[^>]*>/gi, '\n---\n');
html = html.replace(/<blockquote[^>]*>/gi, '\n> ');
html = html.replace(/<\/blockquote>/gi, '\n');
html = html.replace(/<code[^>]*>([\s\S]*?)<\/code>/gi, '`$1`');
html = html.replace(/<pre[^>]*>([\s\S]*?)<\/pre>/gi, '\n```\n$1\n```\n');
html = html.replace(/<strong[^>]*>([\s\S]*?)<\/strong>/gi, '**$1**');
html = html.replace(/<b[^>]*>([\s\S]*?)<\/b>/gi, '**$1**');
html = html.replace(/<em[^>]*>([\s\S]*?)<\/em>/gi, '*$1*');
html = html.replace(/<i[^>]*>([\s\S]*?)<\/i>/gi, '*$1*');
html = html.replace(/<a[^>]*href=["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi, '$2');
html = html.replace(/<[^>]+>/g, '');

html = html.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&mdash;/g, '\u2014').replace(/&ndash;/g, '\u2013').replace(/&hellip;/g, '\u2026').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(n));

html = html.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

if (html.length > 40000) html = html.slice(0, 40000) + '\n\n_[Content truncated at 40,000 characters]_';

if (html.length < 50) return [{ json: { error: true, message: 'We couldn\'t extract readable text from this page. Try copying the text manually.' } }];

return [{ json: { text: html, ytUploadDate } }];

const body = $json.body || {};
const style = body.style || 'Harvard';
const src = body.source || {};
const kind = src.kind || 'link';
const label = src.label || '';
const meta = src.meta || {};


// Build a source-specific context block
let sourceBlock = '';
if (kind === 'link') {
  sourceBlock = `TYPE: Web article / page
URL: ${label}
SCRAPED PAGE TEXT (first ~4000 chars):
${(meta.scrapedText || '').slice(0, 4000)}`;
} else if (kind === 'youtube') {
  sourceBlock = `TYPE: YouTube video
URL: ${meta.url || label}
TITLE: ${meta.title || label}
CHANNEL / AUTHOR: ${meta.author || ''}
SCRAPED PAGE TEXT (for upload year + description, first ~3000 chars):
${(meta.scrapedText || '').slice(0, 3000)}`;
} else if (kind === 'kb') {
  sourceBlock = `TYPE: Uploaded document (from student's Knowledge Bay)
FILE NAME: ${label}
DOCUMENT TEXT (first ~4000 chars):
${(meta.content || '').slice(0, 4000)}`;
} else if (kind === 'upload') {
  sourceBlock = `TYPE: Newly uploaded document
FILE NAME: ${label}
DOCUMENT TEXT (first ~4000 chars):
${(meta.content || '').slice(0, 4000)}`;
}

const styleRules = {
  Harvard:  "Harvard referencing style (author-date). Format: Surname, Initial. (Year) 'Title', Source, Available at: URL (Accessed: date). Use italics conventions via plain text.",
  APA:      "APA 7th edition. Format: Surname, I. (Year). Title. Source. URL",
  MLA:      "MLA 9th edition. Format: Surname, First Name. \"Title.\" Source, Day Month Year, URL.",
  Chicago:  "Chicago (author-date). Format: Surname, First Name. Year. \"Title.\" Source. URL.",
};

const prompt = `You are a citation generator. Produce ONE correctly formatted reference in ${style} style for the source below.

STYLE RULES: ${styleRules[style] || styleRules.Harvard}

RULES:
- Output ONLY the finished reference line — no preamble, no explanation, no bullet, no quotes around the whole thing.
- If the exact year, author, or title is missing, infer the most likely value from the provided text. Never output placeholders like "n.d." unless there is genuinely no date clue anywhere.
- For YouTube: author = channel name, title = video title, year = upload year from the scraped page.
- For uploaded documents with no explicit author, use the filename (without extension) as the title and write "Anon." as author only if no author appears in the document text.
- Use a hanging-indent-ready single line (no manual line breaks).

SOURCE:
${sourceBlock}

Now output the single ${style} reference line:`;

return [{
  json: {
    geminiBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 800
      }
    }
  }
}];

const response = $input.first().json;
let citation = '';

try {
  if (response.body && response.body.candidates && response.body.candidates.length > 0) {
    const parts = response.body.candidates[0].content?.parts || [];
    citation = parts.map(p => p.text || '').join('');
  }
  if (!citation && response.candidates && response.candidates.length > 0) {
    citation = (response.candidates[0].content?.parts || []).map(p => p.text || '').join('');
  }
} catch (e) { citation = ''; }

citation = citation
  .replace(/^```[\w]*\s*/i, '')
  .replace(/\s*```$/i, '')
  .replace(/^["']|["']$/g, '')
  .trim();

if (!citation) citation = '[Unable to generate citation — please check the source]';

return [{ json: { citation } }];

