    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, doc.fieldName);
      base64 = buffer.toString('base64');
    } catch (e) {
      base64 = null;
    }
  } else if (doc.driveFileId && doc.driveAccessToken) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://www.googleapis.com/drive/v3/files/${doc.driveFileId}?alt=media`,
        headers: { Authorization: `Bearer ${doc.driveAccessToken}` },
        encoding: 'arraybuffer',
        json: false,
      });
      const buf = Buffer.isBuffer(res) ? res : Buffer.from(res);
      base64 = buf.toString('base64');
    } catch (e) {
      base64 = null;
    }
  }

  body.scannedPdfDocs = [{ ...doc, base64 }, ...docs.slice(1)];
}

return [{ json: { ...item.json, body } }];

